foreach ($conf['_headers'] as $name => $values) {
    foreach ($values as $value) {
        $value = (string) $value;
        if ($value === '') {
            $conf[\CURLOPT_HTTPHEADER][] = "$name;";
        } else {
            $conf[\CURLOPT_HTTPHEADER][] = "$name: $value";
        }
    }
}
